	/// <summary>
	/// Overrides <see cref="P:Terraria.Main.CurrentPlayer" />. For example, <c>using var _currentPlr = new Main.CurrentPlayerOverride(player);</c> would result in Main.CurrentPlayer returning the specified player until the end of the current scope.
	/// <br /><br /> Used internally to make <see cref="T:Terraria.ModLoader.ModAccessorySlot" /> access a specific player rather than <see cref="P:Terraria.Main.LocalPlayer" />.
	/// </summary>
	public ref struct CurrentPlayerOverride
	{
		private Player _prevPlayer;

		public CurrentPlayerOverride(Player player)
		{
			_prevPlayer = _currentPlayerOverride;
			_currentPlayerOverride = player;
		}

		public void Dispose()
		{
			_currentPlayerOverride = _prevPlayer;
		}
	}

