	public static bool ShouldDrawInfoIconsHorizontally
	{
		get
		{
			if (_cannotDrawAccessoriesHorizontally)
			{
				return false;
			}
			if (mapStyle == 1 && mapEnabled && screenHeight < 820)
			{
				return false;
			}
			if (mapStyle != 1 && screenWidth < 855)
			{
				return false;
			}
			if (PlayerInput.UsingGamepad)
			{
				return false;
			}
			return true;
		}
	}

