				offset.Y -= 10f * gravdir;
				break;
			case 682:
				num = 4f;
				break;
			case 4953:
				num = -4f;
				break;
			case 758:
				num -= 20f;
				offset.Y += 0f * gravdir;
				break;
			case 759:
				num -= 18f;
				offset.Y += 2f * gravdir;
				break;
			case 760:
				num -= 12f;
				offset.Y += 2f * gravdir;
				break;
			case 1946:
				num -= 12f;
				offset.Y += 2f * gravdir;
				break;
			case 779:
				num = 0f;
				offset.Y += 2f * gravdir;
				break;
			case 5134:
				num = 0f;
				offset.Y += 2f * gravdir;
				break;
			case 905:
				num = -5f;
				offset.Y += 0f * gravdir;
				break;
			case 930:
				num = 4f;
				offset.Y += 2f * gravdir;
				break;
			case 3788:
				num = 2f;
				offset.Y += 2f * gravdir;
				break;
			}
			break;
		}
		offset.X = num;
		ItemLoader.HoldoutOffset(gravdir, itemtype, ref offset);
		return offset;
	}

	public static void SetupTileMerge()
	{
		int count = TileID.Count;
		tileMerge = new bool[count][];
		for (int i = 0; i < tileMerge.Length; i++)
		{
			tileMerge[i] = new bool[count];
		}
		SetupAllBlockMerge();
	}

	internal static void SetupAllBlockMerge()
	{
		for (int i = 0; i < TileLoader.TileCount; i++)
		{
			bool flag = i == 10 || i == 387 || i == 541;
			bool? flag2 = TileID.Sets.BlockMergesWithMergeAllBlockOverride[i];
			if (flag2.HasValue)
			{
				bool valueOrDefault = flag2.GetValueOrDefault();
				TileID.Sets.BlockMergesWithMergeAllBlock[i] = valueOrDefault;
				continue;
			}
			if (TileLoader.IsClosedDoor(i))
			{
				flag = true;
			}
			TileID.Sets.BlockMergesWithMergeAllBlock[i] = !flag && tileSolid[i] && !tileSolidTop[i];
		}
	}

