	public static void AnglerQuestSwap()
	{
		if (netMode == 1)
		{
			return;
		}
		anglerWhoFinishedToday.Clear();
		anglerQuestFinished = false;
		bool flag = NPC.downedBoss1 || NPC.downedBoss2 || NPC.downedBoss3 || hardMode || NPC.downedSlimeKing || NPC.downedQueenBee;
		bool notAvailable = true;
		int num = 0;
		while (notAvailable)
		{
			if (++num > 1000)
			{
				anglerQuest = 0;
				Logging.tML.Warn((object)"AnglerQuestSwap try count limit exceeded, a mod might have bad IsAnglerQuestAvailable logic");
				break;
			}
			notAvailable = false;
			anglerQuest = rand.Next(anglerQuestItemNetIDs.Length);
			int num2 = anglerQuestItemNetIDs[anglerQuest];
			if (num2 == 2454 && (!hardMode || WorldGen.crimson))
			{
				notAvailable = true;
			}
			if (num2 == 2457 && WorldGen.crimson)
			{
				notAvailable = true;
			}
			if (num2 == 2462 && !hardMode)
			{
				notAvailable = true;
			}
			if (num2 == 2463 && (!hardMode || !WorldGen.crimson))
			{
				notAvailable = true;
			}
			if (num2 == 2465 && !hardMode)
			{
				notAvailable = true;
			}
			if (num2 == 2468 && !hardMode)
			{
				notAvailable = true;
			}
			if (num2 == 2471 && !hardMode)
			{
				notAvailable = true;
			}
			if (num2 == 2473 && !hardMode)
			{
				notAvailable = true;
			}
			if (num2 == 2477 && !WorldGen.crimson)
			{
				notAvailable = true;
			}
			if (num2 == 2480 && !hardMode)
			{
				notAvailable = true;
			}
			if (num2 == 2483 && !hardMode)
			{
				notAvailable = true;
			}
			if (num2 == 2484 && !hardMode)
			{
				notAvailable = true;
			}
			if (num2 == 2485 && WorldGen.crimson)
			{
				notAvailable = true;
			}
			if ((num2 == 2476 || num2 == 2453 || num2 == 2473) && !flag)
			{
				notAvailable = true;
			}
			ItemLoader.IsAnglerQuestAvailable(num2, ref notAvailable);
		}
		NetMessage.SendAnglerQuest(-1);
	}

