	private static void ErasePlayer(int i)
	{
		try
		{
			FileUtilities.Delete(PlayerList[i].Path, PlayerList[i].IsCloudSave);
			FileUtilities.Delete(PlayerList[i].Path + ".bak", PlayerList[i].IsCloudSave);
		}
		catch
		{
		}
		PlayerIO.ErasePlayer(PlayerList[i].Path, PlayerList[i].IsCloudSave);
		try
		{
			string text = PlayerList[i].Path.Substring(0, PlayerList[i].Path.Length - 4);
			if (text.Substring(text.Length - 1) != "." && text.Substring(text.Length - 1) != "\\" && Directory.Exists(text))
			{
				Directory.Delete(text, recursive: true);
			}
			LoadPlayers();
		}
		catch
		{
		}
	}

	private static void EraseWorld(int i)
	{
		try
		{
			if (!WorldList[i].IsCloudSave)
			{
				Platform.Get<IPathService>().MoveToRecycleBin(WorldList[i].Path);
				Platform.Get<IPathService>().MoveToRecycleBin(WorldList[i].Path + ".bak");
				for (int j = 2; j <= 9; j++)
				{
					Platform.Get<IPathService>().MoveToRecycleBin(WorldList[i].Path + ".bak" + j);
				}
			}
			else if (SocialAPI.Cloud != null)
			{
				SocialAPI.Cloud.Delete(WorldList[i].Path);
			}
			WorldIO.EraseWorld(WorldList[i].Path, WorldList[i].IsCloudSave);
			LoadWorlds();
		}
		catch
		{
		}
	}

	public static string GetPlayerPathFromName(string playerName, bool cloudSave)
	{
		string pattern = "^(con|prn|aux|nul|com[1-9]|lpt[1-9])$";
		if (Regex.IsMatch(playerName, pattern, RegexOptions.IgnoreCase))
		{
			playerName += "_";
		}
		char[] invalidFileNameChars = Path.GetInvalidFileNameChars();
		string text = "";
		playerName = playerName.Replace(".", "_");
		playerName = playerName.Replace("*", "_");
		string text2 = playerName;
		foreach (char c in text2)
		{
			text += ((!invalidFileNameChars.Contains(c)) ? ((c != ' ') ? c : '_') : '-');
		}
		string text3 = (cloudSave ? CloudPlayerPath : PlayerPath);
		if (FileUtilities.GetFullPath(text3 + Path.DirectorySeparatorChar + text + ".plr", cloudSave).StartsWith("\\\\.\\", StringComparison.Ordinal))
		{
			text += "_";
		}
		if (FileUtilities.Exists(text3 + Path.DirectorySeparatorChar + text + ".plr", cloudSave))
		{
			int num = 2;
			while (FileUtilities.Exists(text3 + Path.DirectorySeparatorChar + text + num + ".plr", cloudSave))
			{
				num++;
			}
			text += num;
		}
		return text3 + Path.DirectorySeparatorChar + text + ".plr";
	}

	public static string GetWorldPathFromName(string worldName, bool cloudSave)
	{
		string pattern = "^(con|prn|aux|nul|com[1-9]|lpt[1-9])$";
		if (Regex.IsMatch(worldName, pattern, RegexOptions.IgnoreCase))
		{
			worldName += "_";
		}
		char[] invalidFileNameChars = Path.GetInvalidFileNameChars();
		string text = "";
		string text2 = worldName;
		foreach (char c in text2)
		{
			text += ((!invalidFileNameChars.Contains(c)) ? ((c != ' ') ? c : '_') : '-');
		}
		text = text.Replace(".", "_");
		text = text.Replace("*", "_");
		string text3 = (cloudSave ? CloudWorldPath : WorldPath);
		if (FileUtilities.GetFullPath(text3 + Path.DirectorySeparatorChar + text + ".wld", cloudSave).StartsWith("\\\\.\\", StringComparison.Ordinal))
		{
			text += "_";
		}
		if (FileUtilities.Exists(text3 + Path.DirectorySeparatorChar + text + ".wld", cloudSave))
		{
			int num = 2;
			while (FileUtilities.Exists(text3 + Path.DirectorySeparatorChar + text + num + ".wld", cloudSave))
			{
				num++;
			}
			text += num;
		}
		return text3 + Path.DirectorySeparatorChar + text + ".wld";
	}

