				int num6 = (int)scaledPosition.Y - rand.Next(50);
				if (player[myPlayer].velocity.Y > 0f)
				{
					num6 -= (int)player[myPlayer].velocity.Y;
				}
				if (rand.Next(5) == 0)
				{
					num5 = rand.Next(500) - 500;
				}
				else if (rand.Next(5) == 0)
				{
					num5 = rand.Next(500) + (int)scaledSize.X;
				}
				if (num5 < 0 || (float)num5 > scaledSize.X)
				{
					num6 += rand.Next((int)((double)scaledSize.Y * 0.8)) + (int)((double)scaledSize.Y * 0.1);
				}
				num5 += (int)scaledPosition.X;
				int x = num5 / 16;
				int y = num6 / 16;
				if (WorldGen.InWorld(x, y) && tile[x, y] != null && !tile[x, y].nactive() && tile[x, y].wall == 0)
				{
					int num7 = Dust.NewDust(new Vector2((float)num5, (float)num6), 10, 10, 76);
					dust[num7].scale += cloudAlpha * 0.2f;
					dust[num7].velocity.Y = 3f + (float)rand.Next(30) * 0.1f;
					dust[num7].velocity.Y *= dust[num7].scale;
					if (!raining)
					{
						dust[num7].velocity.X = windSpeedCurrent + (float)rand.Next(-10, 10) * 0.1f;
						dust[num7].velocity.X += windSpeedCurrent * 15f;
					}
					else
					{
						dust[num7].velocity.X = (float)Math.Sqrt(Math.Abs(windSpeedCurrent)) * (float)Math.Sign(windSpeedCurrent) * (cloudAlpha + 0.5f) * 10f + rand.NextFloat() * 0.2f - 0.1f;
						dust[num7].velocity.Y *= 0.5f;
					}
					dust[num7].velocity.Y *= 1f + 0.3f * cloudAlpha;
					dust[num7].scale += cloudAlpha * 0.2f;
					if (flag)
					{
						dust[num7].scale -= 0.5f;
					}
					Dust obj = dust[num7];
					obj.velocity *= 1f + cloudAlpha * 0.5f;
				}
			}
			catch
			{
			}
		}
	}

	public static void checkXMas()
	{
		DateTime now = DateTime.Now;
		int day = now.Day;
		int month = now.Month;
		if (day >= 15 && month == 12)
		{
			xMas = true;
		}
		else
		{
			xMas = false;
		}
		if (forceXMasForToday)
		{
			xMas = true;
		}
	}

	public static void checkHalloween()
	{
		DateTime now = DateTime.Now;
		int day = now.Day;
		int month = now.Month;
		if (day >= 10 && month == 10)
		{
			halloween = true;
		}
		else if (day <= 1 && month == 11)
		{
			halloween = true;
		}
		else
		{
			halloween = false;
		}
		if (forceHalloweenForToday)
		{
			halloween = true;
		}
	}

	public void updateCloudLayer()
	{
		if (netMode == 1 || (netMode == 0 && gameMenu))
		{
			return;
		}
		int num = 86400;
		int num2 = num / 24;
		float num3 = Math.Max(1f, 1f + 4f * cloudAlpha);
		if (cloudBGActive > 0f)
		{
			if (cloudBGActive > 1f)
			{
				cloudBGActive -= (float)desiredWorldEventsUpdateRate / num3;
			}
			if (cloudBGActive < 1f)
			{
				cloudBGActive = 1f;
			}
			if (cloudBGActive == 1f && rand.NextDouble() <= desiredWorldEventsUpdateRate / (double)((float)(num2 * 2) * num3))
			{
				cloudBGActive = -rand.Next(num2 * 4, num * 4);
				if (netMode == 2)
				{
					NetMessage.SendData(7);
				}
			}
			return;
		}
		if (cloudBGActive < 0f)
		{
			cloudBGActive += (float)desiredWorldEventsUpdateRate * num3;
			if (raining)
			{
				cloudBGActive += (float)(2.0 * desiredWorldEventsUpdateRate) * num3;
			}
		}
		if (cloudBGActive > 0f)
		{
			cloudBGActive = 0f;
		}
		if (cloudBGActive == 0f && rand.NextDouble() <= (double)num3 * desiredWorldEventsUpdateRate / (double)(num2 * 12))
		{
			cloudBGActive = rand.Next(num2 * 3, num * 2);
			if (netMode == 2)
			{
				NetMessage.SendData(7);
			}
		}
		else if (IsItStorming)
		{
			cloudBGActive = rand.Next(num2, num2 * 4);
			if (netMode == 2)
			{
				NetMessage.SendData(7);
			}
		}
	}

