				obj.velocity *= 1.75f;
				if (i % 3 == 0)
				{
					Dust obj2 = Main.dust[num];
					obj2.velocity *= 1.5f;
				}
				Main.dust[num].noLightEmittence = true;
				Main.dust[num].noGravity = true;
			}
			break;
		}
		case 6:
