	public static void Ambience()
	{
		//IL_0021: Unknown result type (might be due to invalid IL or missing references)
		//IL_0026: Unknown result type (might be due to invalid IL or missing references)
		//IL_0068: Unknown result type (might be due to invalid IL or missing references)
		//IL_014f: Unknown result type (might be due to invalid IL or missing references)
		ambientCounter++;
		if (ambientCounter >= 15)
		{
			ambientCounter = 0;
			LocalPlayer.Center.ToPoint();
			float volume2 = MathHelper.Clamp(ambientWaterfallStrength / 50f * (1f - shimmerAlpha), 0f, 1f);
			HandleAmbientSound(in SoundID.Waterfall, ref waterfallSoundSlot, volume2, new Vector2(ambientWaterfallX, ambientWaterfallY));
			float num = Math.Abs(ambientLavaX - (screenPosition.X + (float)(screenWidth / 2))) + Math.Abs(ambientLavaY - (screenPosition.Y + (float)(screenHeight / 2)));
			float num2 = Math.Abs(ambientLavafallX - (screenPosition.X + (float)(screenWidth / 2))) + Math.Abs(ambientLavafallY - (screenPosition.Y + (float)(screenHeight / 2)));
			float num3 = ambientLavaX;
			float num4 = ambientLavaY;
			if (num2 < num)
			{
				num3 = ambientLavafallX;
				num4 = ambientLavafallY;
			}
			float num5 = ambientLavafallStrength + ambientLavaStrength;
			float volume3 = ((ambientLavaStrength > 0f) ? MathHelper.Clamp(num5 / 50f, 0f, 1f) : 0f);
			HandleAmbientSound(in SoundID.Lavafall, ref lavafallSoundSlot, volume3, new Vector2(num3, num4));
		}
		static void HandleAmbientSound(in SoundStyle soundStyle, ref SlotId slot, float volume, Vector2 position)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_005a: Unknown result type (might be due to invalid IL or missing references)
			//IL_005f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0044: Unknown result type (might be due to invalid IL or missing references)
			//IL_001b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			SoundEngine.TryGetActiveSound(slot, out ActiveSound result);
			if (volume > 0f)
			{
				if (result == null)
				{
					slot = SoundEngine.PlaySound(in soundStyle, position);
					if (!SoundEngine.TryGetActiveSound(slot, out result))
					{
						return;
					}
				}
				result.Volume = volume;
				result.Position = position;
			}
			else if (result != null)
			{
				result.Stop();
				slot = SlotId.Invalid;
			}
		}
	}

