						{
							butterflyCageFrame[num51, num52] += 8;
						}
					}
				}
				else if (butterflyCageFrameCounter[num51, num52] >= num53)
				{
					butterflyCageFrameCounter[num51, num52] = 0;
					butterflyCageFrame[num51, num52]++;
					if (butterflyCageFrame[num51, num52] > 15)
					{
						butterflyCageFrame[num51, num52] = 8;
					}
					if ((butterflyCageFrame[num51, num52] == 9 || butterflyCageFrame[num51, num52] == 12 || butterflyCageFrame[num51, num52] == 14) && rand.Next(10) == 0)
					{
						butterflyCageFrame[num51, num52] -= 8;
					}
				}
			}
		}
		UpdateDragonflyJarFrames();
		for (int num54 = 0; num54 < 3; num54++)
		{
			for (int num55 = 0; num55 < cageFrames; num55++)
			{
				jellyfishCageFrameCounter[num54, num55]++;
				if (jellyfishCageMode[num54, num55] == 0 && rand.Next(1800) == 0)
				{
					jellyfishCageMode[num54, num55] = 1;
				}
				if (jellyfishCageMode[num54, num55] == 2 && rand.Next(60) == 0)
				{
					jellyfishCageMode[num54, num55] = 3;
				}
				int num56 = 1;
				if (jellyfishCageMode[num54, num55] == 0)
				{
					num56 = rand.Next(10, 20);
				}
				if (jellyfishCageMode[num54, num55] == 1)
				{
					num56 = rand.Next(15, 25);
				}
				if (jellyfishCageMode[num54, num55] == 2)
				{
					num56 = rand.Next(4, 9);
				}
				if (jellyfishCageMode[num54, num55] == 3)
				{
					num56 = rand.Next(15, 25);
				}
				if (jellyfishCageMode[num54, num55] == 0 && jellyfishCageFrame[num54, num55] <= 3 && jellyfishCageFrameCounter[num54, num55] >= num56)
				{
					jellyfishCageFrameCounter[num54, num55] = 0;
					jellyfishCageFrame[num54, num55]++;
					if (jellyfishCageFrame[num54, num55] >= 4)
					{
						jellyfishCageFrame[num54, num55] = 0;
					}
				}
				if (jellyfishCageMode[num54, num55] == 1 && jellyfishCageFrame[num54, num55] <= 7 && jellyfishCageFrameCounter[num54, num55] >= num56)
				{
					jellyfishCageFrameCounter[num54, num55] = 0;
					jellyfishCageFrame[num54, num55]++;
					if (jellyfishCageFrame[num54, num55] >= 7)
					{
						jellyfishCageMode[num54, num55] = 2;
					}
				}
				if (jellyfishCageMode[num54, num55] == 2 && jellyfishCageFrame[num54, num55] <= 9 && jellyfishCageFrameCounter[num54, num55] >= num56)
				{
					jellyfishCageFrameCounter[num54, num55] = 0;
					jellyfishCageFrame[num54, num55]++;
					if (jellyfishCageFrame[num54, num55] >= 9)
					{
						jellyfishCageFrame[num54, num55] = 7;
					}
				}
				if (jellyfishCageMode[num54, num55] == 3 && jellyfishCageFrame[num54, num55] <= 10 && jellyfishCageFrameCounter[num54, num55] >= num56)
				{
					jellyfishCageFrameCounter[num54, num55] = 0;
					jellyfishCageFrame[num54, num55]++;
					if (jellyfishCageFrame[num54, num55] >= 10)
					{
						jellyfishCageFrame[num54, num55] = 3;
						jellyfishCageMode[num54, num55] = 0;
					}
				}
			}
		}
	}

	private static void UpdateOwlCageFrames()
	{
		for (int i = 0; i < cageFrames; i++)
		{
			UpdateOwlCageFrame(owlCageFrame, owlCageFrameCounter, i);
		}
	}

	private static void UpdateDragonflyJarFrames()
	{
		for (int i = 0; i < dragonflyJarFrameCounter.GetLength(0); i++)
		{
			for (int j = 0; j < cageFrames; j++)
			{
				UpdateDragonflyJarFrame(dragonflyJarFrame, dragonflyJarFrameCounter, i, j);
			}
		}
	}

	private static void UpdateOwlCageFrame(int[] frames, int[] frameCounters, int style)
	{
		if (frameCounters[style] % 40 != 0 || rand.Next(80) == 0)
		{
			frameCounters[style]++;
		}
		if ((frameCounters[style] + 1) % 40 == 39)
		{
			frameCounters[style] = 40 * rand.Next(4);
		}
		int num = frameCounters[style] % 40 / 10;
		int num2 = frameCounters[style] / 40;
		int num3 = 0;
		switch (num2)
		{
		case 0:
			if (num == 3)
			{
				num = 1;
			}
			num3 = num;
			break;
		case 1:
			if (num == 3)
			{
				num = 1;
			}
			num3 = 0;
			if (num != 0)
			{
				num3 = 8 - num;
			}
			break;
		case 2:
			num3 = 0;
			if (num != 0)
			{
				num3 = 7 + num;
			}
			break;
		case 3:
			num3 = 0;
			if (num != 0)
			{
				num3 = 11 + num;
			}
			break;
		}
		frames[style] = num3;
	}

	private static void UpdateDragonflyJarFrame(int[,] frames, int[,] frameCounters, int style, int variation)
	{
		frameCounters[style, variation]++;
		switch (frames[style, variation])
		{
		case 0:
			if (frameCounters[style, variation] >= 300 && rand.Next(60) == 0)
			{
				frameCounters[style, variation] = 0;
				frames[style, variation] = rand.NextFromList<int>(1, 5, 9);
			}
			break;
		case 1:
		case 5:
		case 9:
			if (frameCounters[style, variation] >= 100)
			{
				frameCounters[style, variation] = 0;
				if (frames[style, variation] == 1)
				{
					frames[style, variation] = rand.NextFromList<int>(0, 5, 5, 9, 9);
				}
				else
				{
					frames[style, variation] = 1;
				}
			}
			else if (frameCounters[style, variation] >= 6)
			{
				frameCounters[style, variation] = 0;
				frames[style, variation]++;
			}
			break;
		case 2:
		case 3:
		case 4:
		case 6:
		case 7:
		case 8:
		case 10:
		case 11:
		case 12:
		{
			int num = frames[style, variation] - 1;
			int num2 = num % 4;
			num2--;
			int num3 = frameCounters[style, variation] / 4 % 4;
			if (num3 > 2)
			{
				num3 = 4 - num3;
			}
			int num4 = num - num2 + 1 + num3;
			frames[style, variation] = num4;
			if (frameCounters[style, variation] >= 40 && rand.Next(30) == 0)
			{
				frameCounters[style, variation] = 100;
				frames[style, variation] = num - num2 + 1 - 1;
			}
			break;
		}
		}
	}

