					localizedText = Lang.tip[55];
				}
				int weaponDamage = player[myPlayer].GetWeaponDamage(item, forTooltip: true);
				toolTipLine[numLines] = weaponDamage + localizedText.Value;
				toolTipNames[numLines] = "Damage";
