		{
			num = (player[myPlayer].ZoneHallow ? 6 : ((!player[myPlayer].ZoneCorrupt) ? (player[myPlayer].ZoneCrimson ? 8 : ((SceneMetrics.HoneyBlockCount <= 400) ? 4 : 3)) : ((SceneMetrics.BloodTileCount <= SceneMetrics.EvilTileCount) ? 1 : 8)));
		}
