		else
		{
			ServerSideCharacter = false;
			myPlayer = 0;
			data.SetAsActive();
			player[myPlayer].position = Vector2.Zero;
			LoadWorlds();
			SoundEngine.PlaySound(10);
			menuMode = 6;
		}
	}

