	/// <summary>
	/// Syncs rain state if <see cref="M:Terraria.Main.StartRain" /> or <see cref="M:Terraria.Main.StopRain" /> were called in the same tick and caused a change to <seealso cref="F:Terraria.Main.maxRaining" />.
	/// <br>Can be called on any side, but only the server will actually sync it.</br>
	/// </summary>
	public static void SyncRain()
	{
		if (maxRaining != oldMaxRaining)
		{
			if (netMode == 2)
			{
				NetMessage.SendData(7);
			}
			oldMaxRaining = maxRaining;
		}
	}

	internal void InitTMLContentManager()
	{
		if (dedServ)
		{
			return;
		}
		string text;
		if (SocialAPI.Mode == SocialMode.Steam)
		{
			text = Path.Combine(Steam.GetSteamTerrariaInstallDir(), "Content");
		}
		else if (InstallVerifier.DistributionPlatform == DistributionPlatform.GoG)
		{
			text = Path.Combine(Path.GetDirectoryName(InstallVerifier.vanillaExePath), "Content");
			Logging.tML.Info((object)("Content folder of Terraria GOG Install Location assumed to be: " + Path.GetFullPath(text)));
		}
		else
		{
			text = (Platform.IsOSX ? "../Terraria/Terraria.app/Contents/Resources/Content" : "../Terraria/Content");
			if (!Directory.Exists(text))
			{
				text = (Platform.IsOSX ? "../Terraria.app/Contents/Resources/Content" : "../Content");
			}
		}
		if (!Directory.Exists(text))
		{
			ErrorReporting.FatalExit(Language.GetTextValue("tModLoader.ContentFolderNotFound"));
		}
		if (!File.Exists(Path.Combine(text, "Images", "Projectile_651.xnb")))
		{
			Utils.OpenToURL("https://github.com/tModLoader/tModLoader/wiki/Basic-tModLoader-Usage-FAQ#terraria-is-out-of-date-or-terraria-is-on-a-legacy-version");
			ErrorReporting.FatalExit(Language.GetTextValue("tModLoader.TerrariaLegacyBranchMessage"));
		}
		if (!File.Exists(Path.Combine(text, "Images", "Projectile_981.xnb")))
		{
			Utils.OpenToURL("https://github.com/tModLoader/tModLoader/wiki/Basic-tModLoader-Usage-FAQ#terraria-is-out-of-date-or-terraria-is-on-a-legacy-version");
			ErrorReporting.FatalExit(Language.GetTextValue("tModLoader.TerrariaOutOfDateMessage"));
		}
		TMLContentManager overrideContentManager = null;
		if (Directory.Exists(Path.Combine("Content", "Images")))
		{
			overrideContentManager = new TMLContentManager(((Game)this).Content.ServiceProvider, "Content", null);
		}
		((Game)this).Content = (ContentManager)(object)new TMLContentManager(((Game)this).Content.ServiceProvider, text, overrideContentManager);
	}

