	private static void PrepareLoadedModsAndConfigsForSingleplayer()
	{
		bool flag = false;
		List<ReloadRequiredExplanation> list = new List<ReloadRequiredExplanation>();
		IEnumerable<LocalMod> source = ModOrganizer.RecheckVersionsToLoad();
		Mod[] mods = Terraria.ModLoader.ModLoader.Mods;
		foreach (Mod loadedMod in mods)
		{
			if (!(loadedMod is ModLoaderMod) && loadedMod.File != null)
			{
				LocalMod localMod2 = source.First((LocalMod mod) => mod.Name == loadedMod.Name);
				if (localMod2.modFile.path != loadedMod.File.path)
				{
					list.Add(new ReloadRequiredExplanation(2, localMod2.Name, localMod2, Language.GetTextValue("tModLoader.ReloadRequiredExplanationSwitchVersion", "FFFACD", localMod2.Version, loadedMod.Version)));
					flag = true;
				}
			}
		}
		if (ConfigManager.AnyModNeedsReloadCheckOnly(out List<Mod> modsWithChangedConfigs))
		{
			flag = true;
			foreach (Mod mod2 in modsWithChangedConfigs)
			{
				LocalMod localMod3 = source.First((LocalMod localMod) => localMod.Name == mod2.Name);
				list.Add(new ReloadRequiredExplanation(5, mod2.Name, localMod3, Language.GetTextValue("tModLoader.ReloadRequiredExplanationConfigChangedRestore", "DDA0DD")));
			}
		}
		if (flag)
		{
			string textValue = Language.GetTextValue("tModLoader.ReloadRequiredReloadAndContinue");
			Interface.serverModsDifferMessage.Show(Language.GetTextValue("tModLoader.ReloadRequiredSinglePlayerMessage", textValue), 0, null, textValue, delegate
			{
				Terraria.ModLoader.ModLoader.OnSuccessfulLoad = (Action)Delegate.Combine(Terraria.ModLoader.ModLoader.OnSuccessfulLoad, (Action)delegate
				{
					menuMode = 1;
				});
				Terraria.ModLoader.ModLoader.Reload();
			}, Language.GetTextValue("tModLoader.ModConfigBack"), delegate
			{
			}, list);
		}
		else
		{
			ConfigManager.LoadAll();
			ConfigManager.OnChangedAll();
		}
	}

